import json
import sys
from collections import deque, defaultdict

def main():
    journal_path, deg_path, out_path = sys.argv[1], sys.argv[2], sys.argv[3]

    with open(journal_path) as f:
        journal = json.load(f)
    with open(deg_path) as f:
        deg = json.load(f)

    # Parse nodes and edges
    nodes = {n['id']: {'terminal': n['terminal']} for n in deg['nodes']}
    edges = []
    for e in deg['edges']:
        edges.append((e['src'], e['dst'], e.get('gated', False), e.get('wrong', False)))

    # Compute depths via BFS from 'start'
    start_node = None
    for nid, data in nodes.items():
        if nid == 'start':
            start_node = nid
            break

    depth = {}
    visited = set()
    queue = deque([(start_node, 0)])

    while queue:
        node, d = queue.popleft()
        if node in visited:
            continue
        visited.add(node)
        depth[node] = d

        # Find all outgoing edges (including wrong)
        for src, dst, gated, wrong in edges:
            if src == node:
                if dst not in visited:
                    queue.append((dst, d + 1))

    # Assign depth to unreachable nodes
    if depth:
        max_reachable_depth = max(depth.values())
        for nid in nodes:
            if nid not in depth:
                depth[nid] = max_reachable_depth + 1
    else:
        # No nodes reachable (unlikely)
        for nid in nodes:
            depth[nid] = 0

    # Group nodes by depth and sort lexicographically
    depth_groups = defaultdict(list)
    for nid in nodes:
        depth_groups[depth[nid]].append(nid)

    # Sort each group lexicographically
    for d in depth_groups:
        depth_groups[d].sort()

    # Compute coordinates and max_depth/max_column_size
    node_pos = {}
    max_depth = 0
    max_column_size = 0
    for d in depth_groups:
        max_depth = max(max_depth, d)
        max_column_size = max(max_column_size, len(depth_groups[d]))

    for d, nids in depth_groups.items():
        for i, nid in enumerate(nids):
            x = 80 + d * 170
            y = 70 + i * 90
            node_pos[nid] = (x, y)

    # Calculate canvas size
    W = 160 + max_depth * 170
    H = 140 + (max_column_size - 1) * 90

    # Extract route from journal
    route = []
    for event in journal['events']:
        if event['action'] == 'commit':
            route.append(event['node_id'])

    # Generate SVG
    svg = ['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {} {}">'.format(W, H)]
    svg.append('<title>{} - {}</title>'.format(deg['id'], journal['model']))
    svg.append('''<style>
        .edge { stroke: #888; stroke-width: 2; }
        .edge.gated { stroke: #c0392b; }
        .edge.wrong { stroke: #f39c12; }
        .route { fill: none; stroke: #2a78d6; stroke-width: 4; }
        .node { fill: #ffffff; stroke: #000; stroke-width: 2; }
        .node.start { fill: #e6f7ff; }
        .node.exit { fill: #d4edda; }
        .node.deadend { fill: #f8d7da; }
        .step { font-family: sans-serif; font-size: 14px; }
    </style>''')

    # Draw edges
    for src, dst, gated, wrong in edges:
        x1, y1 = node_pos[src]
        x2, y2 = node_pos[dst]
        cls = 'edge'
        if gated:
            cls += ' gated'
        if wrong:
            cls += ' wrong'
        svg.append('<line x1="{}" y1="{}" x2="{}" y2="{}" class="{}"/>'.format(x1, y1, x2, y2, cls))

    # Draw route
    points = ' '.join([f'{node_pos[nid][0]},{node_pos[nid][1]}' for nid in route])
    svg.append('<polyline class="route" points="{}"/>'.format(points))

    # Draw nodes
    for nid in nodes:
        x, y = node_pos[nid]
        cls = 'node'
        if nid == 'start':
            cls += ' start'
        if nodes[nid]['terminal']:
            cls += ' exit'
        else:
            # Check if dead end (no outgoing edges)
            has_outgoing = any(src == nid for src, _, _, _ in edges)
            if not has_outgoing:
                cls += ' deadend'
        svg.append('<circle cx="{}" cy="{}" r="18" class="{}" data-id="{}"/>'.format(x, y, cls, nid))

    # Add step labels
    step_counts = defaultdict(int)
    for i, event in enumerate(journal['events']):
        if event['action'] == 'commit':
            nid = event['node_id']
            steps_used = event['steps_used']
            x, y = node_pos[nid]
            k = step_counts[nid]
            step_y = y - 26 - 14 * k
            svg.append('<text x="{}" y="{}" class="step" data-step="{}">{}</text>'.format(x, step_y, steps_used, steps_used))
            step_counts[nid] += 1

    svg.append('</svg>')

    with open(out_path, 'w') as f:
        f.write('\n'.join(svg))

if __name__ == '__main__':
    main()
